module.exports = function (RED) {
    function RequirementsOutputNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        node.name = config.name;
        node.model = config.model;
        node.seedingPrompt = "Based on the given input, create me software requirements that cover all the aspects. Give them in a common format for requirements and dont add extra text"
        node.on("input", function (msg) {
            msg.payload = `Processed by agent node: ${node.name || ""}`;
            node.send(msg);
        });
    }

    RED.nodes.registerType("Requirements", RequirementsOutputNode);
}